code_string = """
from qiskit import transpile
def run_and_analyze(circuit, aer_sim):
    tc = transpile(circuit, aer_sim)
    result = aer_sim.run(tc, shots=4096).result()
    counts = result.get_counts()
    # Collect input measurements (lower 5 bits in qiskit ordering)
    # Bitstrings are in order c[9]c[8]...c[0]
    samples = []
    for bs, cnt in counts.items():
        bs = bs.replace(' ', '')
        # input bits are c[0..4] -> last 5 chars
        in_bits = bs[-5:]
        # convert to integer
        x_int = int(in_bits, 2)
        if x_int < 27:
            samples.append((x_int, cnt))
    # Try each candidate s in {0,1,2}^3 except 000
    # For each s, check sum over samples where x (as ternary) dot s mod 3 != 0
    # The correct s should have all weight on x with x.s = 0 mod 3
    def to_trits(x, n=3):
        t = []
        for _ in range(n):
            t.append(x % 3)
            x //= 3
        return t
    best_s = None
    best_score = -1
    for s_int in range(1, 27):
        s_trits = to_trits(s_int)
        score = 0
        total = 0
        for x, cnt in samples:
            x_trits = to_trits(x)
            dot = sum(a*b for a,b in zip(x_trits, s_trits)) % 3
            total += cnt
            if dot == 0:
                score += cnt
        if total > 0:
            ratio = score / total
            if ratio > best_score:
                best_score = ratio
                best_s = s_trits
    prediction = ''.join(str(t) for t in best_s)
    return prediction
"""
